container.customCss:
:root {
  --lb-overlay-surface-base: #0B1220F0;
  --lb-overlay-surface-glass: #0B1220DB;
  --lb-overlay-surface-strong: #070C17F7;
  --lb-overlay-surface-opaque: #070C17;
  --lb-overlay-surface-raised: #16203AF0;
  --lb-overlay-surface-muted: #1E2A44E6;
  --lb-overlay-surface-scrim: #070C17B8;
  --lb-overlay-border-subtle: #C9A24A66;
  --lb-overlay-border-strong: #C9A24AB3;
  --lb-overlay-border-width: 1.5px;
  --lb-overlay-divider: #C9A24A33;
  --lb-overlay-highlight: #F0D78C;
  --lb-overlay-highlight-soft: #C9A24A;
  --lb-overlay-warning: #F0D78C;
  --lb-overlay-brand-primary: #C9A24A;
  --lb-overlay-brand-secondary: #F0D78C;
  --lb-overlay-info: #2F8CFF;
  --lb-overlay-text-primary: #EDE6D6;
  --lb-overlay-text-secondary: #CFC4AA;
  --lb-overlay-text-muted: #8FA3C4;
  --lb-overlay-team-neutral: #C9A24A;
  --lb-overlay-team-blue: #2F8CFF;
  --lb-overlay-team-blue-soft: #2F8CFF38;
  --lb-overlay-team-red: #D7372B;
  --lb-overlay-team-red-soft: #D7372B38;
  --lb-font-display: "Cinzel", Georgia, serif;
  --lb-font-numeric: "Barlow Condensed", "Roboto Condensed", sans-serif;
  --lb-font-body: "Barlow Condensed", "Roboto Condensed", sans-serif;
}

