container.customCss:
.objectiveBounty-leftTeam {
  border-top: none;
  border-left: 2px solid var(--lb-side-blue);
  overflow: hidden;
  flex-wrap: wrap;
}

.objectiveBounty-rightTeam {
  border-top: none;
  border-right: 2px solid var(--lb-side-red);
  overflow: hidden;
  flex-wrap: wrap;
}
